  1→import {
  2→  animateParallel,
  3→  Block,
  4→  InputFocusScrollView,
  5→  Text,
  6→  useForm,
  7→} from "@prototyp/skeletor";
  8→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
  9→import { RecoveryState } from "@unomed/react-native-matrix-sdk";
 10→import { MatrixService } from "modules/matrix-client/services";
 11→import type React from "react";
 12→import { useEffect, useState } from "react";
 13→import { Image, StyleSheet } from "react-native";
 14→import Toast from "react-native-toast-message";
 15→import {
 16→  Button,
 17→  GoBackHeader,
 18→  Input,
 19→  Loading,
 20→  ScreenLayout,
 21→} from "shared/components";
 22→import { MOCKED_AUTH_DATA } from "shared/const/mocked-auth-data";
 23→import { useNavigateToCorrectScreenHelper } from "shared/hooks";
 24→import { Colors, TextSize } from "shared/styles";
 25→
 26→type FormState = {
 27→  username: string;
 28→  password: string;
 29→};
 30→
 31→const animateUsername = animateParallel(
 32→  {
 33→    opacity: [0, 1],
 34→    translateY: [-20, 0],
 35→  },
 36→  { duration: 200, native: false },
 37→);
 38→
 39→const animatePassword = animateParallel(
 40→  {
 41→    opacity: [0, 1],
 42→    translateY: [-20, 0],
 43→  },
 44→  { duration: 200, native: false },
 45→);
 46→
 47→export const Login: React.FC<NativeStackScreenProps<Routes, "login">> = ({
 48→  navigation,
 49→}) => {
 50→  const [loading, setLoading] = useState(false);
 51→  const [passwordVisible, setPasswordVisible] = useState(false);
 52→  const form = useForm<FormState>({
 53→    username: MOCKED_AUTH_DATA("stjepan").username,
 54→    password: MOCKED_AUTH_DATA("stjepan").password,
 55→  });
 56→
 57→  const navigateToCorrectScreen = useNavigateToCorrectScreenHelper();
 58→
 59→  const submit = async () => {
 60→    try {
 61→      if (!form.validateForm()) return;
 62→      setLoading(true);
 63→      const session = await MatrixService.login(form.state);
 64→      await MatrixService.setup(session);
 65→
 66→      Toast.show({
 67→        type: "success",
 68→        text1: "Successfully signed in",
 69→      });
 70→
 71→      const backupState = await MatrixService.getBackupState();
 72→      const recoveryState = await MatrixService.getRecoveryState();
 73→      const backupExists = backupState === "enabled";
 74→      const recoveryDisabled =
 75→        recoveryState === RecoveryState.Disabled ||
 76→        recoveryState === RecoveryState.Incomplete;
 77→      const isVerified = MatrixService.isDeviceVerified();
 78→      const needsConfirmIdentity =
 79→        !isVerified && backupExists && !recoveryDisabled;
 80→
 81→      if (needsConfirmIdentity) navigation.replace("confirmIdentity");
 82→      else navigateToCorrectScreen();
 83→    } catch (e: unknown) {
 84→      console.error("Failed to authenticate properly: ", e);
 85→
 86→      const error = e as { inner?: { kind?: { tag?: string } } };
 87→      const isRateLimited = error?.inner?.kind?.tag === "LimitExceeded";
 88→
 89→      Toast.show({
 90→        type: "error",
 91→        text1: isRateLimited ? "Too many login attempts" : "Failed to login",
 92→        text2: isRateLimited
 93→          ? "Please wait a moment and try again"
 94→          : "Username or password is incorrect",
 95→      });
 96→    } finally {
 97→      setLoading(false);
 98→    }
 99→  };
100→
101→  useEffect(() => {
102→    if (form.state.username) animateUsername.start();
103→    else animateUsername.reverse();
104→  }, [form.state.username]);
105→
106→  useEffect(() => {
107→    if (form.state.password) animatePassword.start();
108→    else animatePassword.reverse();
109→  }, [form.state.password]);
110→
111→  return (
112→    <ScreenLayout>
113→      {loading && <Loading text="Signing in and syncing..." />}
114→      <InputFocusScrollView>
115→        {(focus) => (
116→          <Block flex={1}>
117→            <GoBackHeader />
118→            <Block gap={8} margins={{ marginBottom: 40 }}>
119→              <Text font="InstrumentSans-Medium" size={TextSize.large}>
120→                Sign in
121→              </Text>
122→              <Text
123→                color={Colors.white80}
124→                font="InstrumentSans-Regular"
125→                size={TextSize.base}
126→              >
127→                Enter your details to sign in.
128→              </Text>
129→            </Block>
130→
131→            <Block gap={8} margins={{ marginBottom: 32 }}>
132→              <Text
133→                style={animateUsername.animations}
134→                size={TextSize.tiny}
135→                color={Colors.white50}
136→                paddings={[0, 16]}
137→              >
138→                Username
139→              </Text>
140→              <Input
141→                placeholder="Username"
142→                value={form.state.username}
143→                keyboardType="email-address"
144→                autoCapitalize="none"
145→                onFocus={focus}
146→                onBlur={() => form.validate("username")}
147→                onChangeText={(value) => form.update("username", value)}
148→              />
149→              <Text
150→                color="red"
151→                opacity={form.validation.username === false ? 1 : 0}
152→                size={TextSize.tiny}
153→                paddings={[0, 16]}
154→                absolute
155→                offsets={{ bottom: -20 }}
156→              >
157→                Please enter a valid username.
158→              </Text>
159→            </Block>
160→
161→            <Block gap={8}>
162→              <Text
163→                style={animatePassword.animations}
164→                size={TextSize.tiny}
165→                color={Colors.white50}
166→                paddings={[0, 16]}
167→              >
168→                Password
169→              </Text>
170→              <Input
171→                placeholder="Password"
172→                secureTextEntry={!passwordVisible}
173→                value={form.state.password}
174→                onFocus={focus}
175→                onBlur={() => form.validate("password")}
176→                onChangeText={(value) => form.update("password", value)}
177→                onSubmitEditing={submit}
178→                rightIcon={
179→                  <Button.Wrapper
180→                    onPress={() => setPasswordVisible((prev) => !prev)}
181→                    hitSlop={8}
182→                    style={styles.passwordVisibleIconContainer}
183→                  >
184→                    <Image
185→                      source={
186→                        passwordVisible
187→                          ? require("assets/icons/eye.png")
188→                          : require("assets/icons/eye-slash.png")
189→                      }
190→                      style={styles.passwordVisibleIcon}
191→                    />
192→                  </Button.Wrapper>
193→                }
194→              />
195→              <Text
196→                color="red"
197→                opacity={form.validation.password === false ? 1 : 0}
198→                size={TextSize.tiny}
199→                paddings={[0, 16]}
200→                absolute
201→                offsets={{ bottom: -20 }}
202→              >
203→                Please enter a valid password.
204→              </Text>
205→            </Block>
206→          </Block>
207→        )}
208→      </InputFocusScrollView>
209→      <Block
210→        paddings={{ padding: 20 }}
211→        gap={12}
212→        justify="flex-end"
213→        minHeight={200}
214→      >
215→        <Button.Primary disabled={loading} onPress={submit}>
216→          Continue
217→        </Button.Primary>
218→      </Block>
219→    </ScreenLayout>
220→  );
221→};
222→
223→const styles = StyleSheet.create({
224→  passwordVisibleIcon: {
225→    width: 20,
226→    height: 20,
227→    tintColor: "white",
228→  },
229→  passwordVisibleIconContainer: {
230→    paddingRight: 16,
231→  },
232→});
