 1→import { useAtomValue } from "jotai";
 2→import { NavigationContainerRef } from "modules/navigation/const";
 3→import { PushNotificationsAtoms } from "modules/push-notifications/jotai";
 4→import { StorageAtoms } from "modules/storage/jotai/atoms";
 5→
 6→export const useNavigateToCorrectScreenHelper = () => {
 7→  const hasSeenNotificationsIntro = useAtomValue(
 8→    PushNotificationsAtoms.hasSeenNotificationsIntro,
 9→  );
10→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
11→
12→  return () => {
13→    if (!hasSeenOnboarding) {
14→      NavigationContainerRef.reset({
15→        index: 0,
16→        routes: [{ name: "onboarding" }],
17→      });
18→      return;
19→    }
20→
21→    if (!hasSeenNotificationsIntro) {
22→      NavigationContainerRef.reset({
23→        index: 0,
24→        routes: [{ name: "notificationsIntro" }],
25→      });
26→      return;
27→    }
28→
29→    NavigationContainerRef.reset({
30→      index: 0,
31→      routes: [{ name: "home" }],
32→    });
33→  };
34→};
