 12→export const VerifyWithDevice: FC<
 13→  NativeStackScreenProps<Routes, "verifyWithDevice">
 14→> = ({ navigation }) => {
 15→  const client = useAtomValue(MatrixAtoms.matrixClient);
 16→  const [isWaiting, setIsWaiting] = useState(true);
 17→  const [deviceId, setDeviceId] = useState<string | null>(null);
 18→
 19→  useEffect(() => {
 20→    // Get the device ID to show the user
 21→    const id = MatrixService.getDeviceId();
 22→    setDeviceId(id);
 23→
 24→    // Check verification status periodically
 25→    const checkInterval = setInterval(async () => {
 26→      const isVerified = MatrixService.isDeviceVerified();
 27→      if (isVerified) {
 28→        clearInterval(checkInterval);
 29→        Toast.show({
 30→          text1: "Device verified successfully! 🎉",
 31→          text2: "You can now access your encrypted messages",
 32→          type: "success",
 33→        });
 34→        navigation.reset({
 35→          index: 0,
 36→          routes: [{ name: "home" }],
 37→        });
 38→      }
 39→    }, 2000);
 40→
 41→    return () => clearInterval(checkInterval);
 42→  }, [navigation]);
 43→
 44→  const handleSkip = () => {
 45→    navigation.goBack();
 46→  };
 47→
 48→  return (
 49→    <ScreenLayout>
 50→      <GoBackHeader />
 51→      <Block flex={1} justify="space-between">
 52→        <Block flex={1} justify="center" align="center" gap={32}>
 53→          <Block gap={12}>
 54→            <Text
 55→              size={TextSize.large}
 56→              textAlign="center"
 57→              font="InstrumentSans-Medium"
 58→            >
 59→              Verify with another device
 60→            </Text>
 61→            <Text
 62→              textAlign="center"
 63→              font="InstrumentSans-Regular"
 64→              color={Colors.white50}
 65→            >
 66→              To verify this device and access your encrypted messages, follow
 67→              these steps on a device that's already verified:
 68→            </Text>
 69→          </Block>
 70→
 71→          <Block
 72→            border={{ borderRadius: 12 }}
 73→            background={Colors.white5}
 74→            paddings={[20, 20]}
 75→            gap={16}
 76→            width="100%"
 77→          >
 78→            <Block flexDirection="row" gap={12}>
 79→              <Text color={Colors.primary} font="InstrumentSans-Bold">
 80→                1.
 81→              </Text>
 82→              <Text color={Colors.white80}>
 83→                Open Element or this app on your other device
 84→              </Text>
 85→            </Block>
 86→            <Block flexDirection="row" gap={12}>
 87→              <Text color={Colors.primary} font="InstrumentSans-Bold">
 88→                2.
 89→              </Text>
 90→              <Text color={Colors.white80}>
 91→                Go to Settings → Security → Sessions
 92→              </Text>
 93→            </Block>
 94→            <Block flexDirection="row" gap={12}>
 95→              <Text color={Colors.primary} font="InstrumentSans-Bold">
 96→                3.
 97→              </Text>
 98→              <Block flex={1}>
 99→                <Text color={Colors.white80}>
100→                  Find this device and tap "Verify"
101→                </Text>
102→                {deviceId && (
103→                  <Text
104→                    color={Colors.white50}
105→                    size={TextSize.small}
106→                    margins={{ marginTop: 4 }}
107→                  >
108→                    Device ID: {deviceId}
109→                  </Text>
110→                )}
111→              </Block>
112→            </Block>
113→            <Block flexDirection="row" gap={12}>
114→              <Text color={Colors.primary} font="InstrumentSans-Bold">
115→                4.
116→              </Text>
117→              <Text color={Colors.white80}>
118→                Compare the emoji sequences and confirm if they match
119→              </Text>
120→            </Block>
121→          </Block>
122→
123→          {isWaiting && (
124→            <Block flexDirection="row" align="center" gap={12}>
125→              <ActivityIndicator color={Colors.primary} />
126→              <Text color={Colors.white50}>
127→                Waiting for verification request...
128→              </Text>
129→            </Block>
130→          )}
131→
132→          <Block
133→            border={{ borderRadius: 12 }}
134→            background={Colors.primary + "20"}
135→            paddings={[12, 16]}
136→            flexDirection="row"
137→            align="center"
138→            gap={12}
139→          >
140→            <Image
141→              source={require("assets/icons/info.png")}
142→              tintColor={Colors.primary}
143→              width={20}
144→              height={20}
145→            />
146→            <Text color={Colors.white80} size={TextSize.small} flex={1}>
147→              Don't have access to another verified device? Use your recovery
148→              key instead.
149→            </Text>
150→          </Block>
151→        </Block>
152→
153→        <Button.Outline onPress={handleSkip}>Go Back</Button.Outline>
154→      </Block>
155→    </ScreenLayout>
156→  );
157→};
