 19→export const EnterRecoveryKey: FC<
 20→  NativeStackScreenProps<Routes, "enterRecoveryKey">
 21→> = () => {
 22→  const [recoveryKey, setRecoveryKey] = useState("");
 23→  const [isLoading, setIsLoading] = useState(false);
 24→  const [hasSeenProtectAccountMessage, setHasSeenProtectAccountMessage] =
 25→    useMMKVBoolean(SecureStoreKeys.HAS_SEEN_PROTECT_ACCOUNT_MESSAGE);
 26→  const navigateToCorrectScreen = useNavigateToCorrectScreenHelper();
 27→
 28→  const handleContinue = async () => {
 29→    if (!recoveryKey.trim()) return;
 30→
 31→    try {
 32→      setIsLoading(true);
 33→      // The recover() method both restores encrypted messages AND verifies the device
 34→      await MatrixService.recoverWithKey(recoveryKey);
 35→      Toast.show({
 36→        text1: "Device verified successfully! 🎉",
 37→        text2: "You can now access your encrypted messages",
 38→        type: "success",
 39→      });
 40→
 41→      if (!hasSeenProtectAccountMessage) setHasSeenProtectAccountMessage(true);
 42→
 43→      navigateToCorrectScreen();
 44→    } catch (error) {
 45→      console.error(error);
 46→      Toast.show({
 47→        text1: "Invalid recovery key",
 48→        text2: "Please check your recovery key and try again",
 49→        type: "error",
 50→      });
 51→    } finally {
 52→      setIsLoading(false);
 53→    }
 54→  };
 55→
 56→  return (
 57→    <ScreenLayout type="modal">
 58→      {isLoading && <Loading text="Verifying with recovery key..." />}
 59→      <GoBackHeader margins={{ marginBottom: 40 }} />
 60→      <KeyboardAvoidingView
 61→        style={{ flex: 1 }}
 62→        behavior={Platform.OS === "ios" ? "padding" : "height"}
 63→      >
 64→        <Block flex={1} justify="space-between">
 65→          <Block justify="center" align="center" gap={32}>
 66→            <Block gap={8}>
 67→              <Text
 68→                size={TextSize.large}
 69→                textAlign="center"
 70→                font="InstrumentSans-Medium"
 71→              >
 72→                Enter your recovery key
 73→              </Text>
 74→              <Text
 75→                textAlign="center"
 76→                font="InstrumentSans-Regular"
 77→                color={Colors.white50}
 78→              >
 79→                This will verify your device and restore access to your
 80→                encrypted message history. Make sure nobody can see this screen.
 81→              </Text>
 82→            </Block>
 83→
 84→            <Block width="100%">
 85→              <Input
 86→                placeholder="Recovery key"
 87→                value={recoveryKey}
 88→                onChangeText={setRecoveryKey}
 89→                autoCapitalize="none"
 90→                autoCorrect={false}
 91→                secureTextEntry
 92→              />
 93→            </Block>
 94→          </Block>
 95→
 96→          <Block width="100%" paddings={[0, 52]} margins={{ marginBottom: 20 }}>
 97→            <Button.Primary
 98→              size="medium"
 99→              width="100%"
100→              onPress={handleContinue}
101→              disabled={!recoveryKey.trim()}
102→            >
103→              Continue
104→            </Button.Primary>
105→          </Block>
106→        </Block>
107→      </KeyboardAvoidingView>
108→    </ScreenLayout>
109→  );
110→};
