 664→  public static forwardMessage = async (
 665→    roomId: string,
 666→    event: EventTimelineItem,
 667→    messageType: ForwardMessageType,
 668→  ) => {
 669→    if (!this.instance) throw new Error("Client not initialized");
 670→    const room = this.instance.getRoom(roomId);
 671→    if (!room) throw new Error("Room not found");
 672→    const timeline = await room.timeline();
 673→    if (!timeline) throw new Error("Timeline not found");
 674→
 675→    if (messageType === "text") {
 676→      const textContent = this.getTextContent(event);
 677→      if (!textContent) throw new Error("Text content not found");
 678→      const messageContent = messageEventContentFromMarkdown(textContent);
 679→      await timeline.send(messageContent);
 680→      return;
 681→    }
 682→
 683→    if (messageType === "image") {
 684→      const imageContent = this.getImageContent(event);
 685→      if (!imageContent) throw new Error("Image content not found");
 686→
 687→      const mediaFile = await this.instance.getMediaFile(
 688→        imageContent.source,
 689→        imageContent.filename,
 690→        imageContent.info?.mimetype || "image/jpeg",
 691→        true,
 692→        undefined,
 693→      );
 694→
 695→      const filePath = mediaFile.path();
 696→      const fileSource: UploadParameters = {
 697→        source: new UploadSource.File({ filename: filePath }),
 698→        caption: imageContent.caption || undefined,
 699→        formattedCaption: undefined,
 700→        mentions: undefined,
 701→        inReplyTo: undefined,
 702→      };
 703→
 704→      const imageHandle = timeline.sendImage(
 705→        fileSource,
 706→        new UploadSource.File({ filename: filePath }),
 707→        {
 708→          height: imageContent.info?.height || BigInt(0),
 709→          width: imageContent.info?.width || BigInt(0),
 710→          mimetype: imageContent.info?.mimetype || "image/jpeg",
 711→          size: imageContent.info?.size || BigInt(0),
 712→          thumbnailInfo: imageContent.info?.thumbnailInfo,
 713→          thumbnailSource: undefined,
 714→          blurhash: imageContent.info?.blurhash || "",
 715→          isAnimated: false,
 716→        },
 717→      );
 718→      await imageHandle.join();
 719→      return;
 720→    }
 721→
 722→    if (messageType === "video") {
 723→      const videoContent = this.getVideoContent(event);
 724→      if (!videoContent) throw new Error("Video content not found");
 725→
 726→      const mediaFile = await this.instance.getMediaFile(
 727→        videoContent.source,
 728→        videoContent.filename,
 729→        videoContent.info?.mimetype || "video/mp4",
 730→        true,
 731→        undefined,
 732→      );
 733→
 734→      const filePath = mediaFile.path();
 735→      const fileSource: UploadParameters = {
 736→        source: new UploadSource.File({ filename: filePath }),
 737→        caption: videoContent.caption || undefined,
 738→        formattedCaption: undefined,
 739→        mentions: undefined,
 740→        inReplyTo: undefined,
 741→      };
 742→
 743→      const videoHandle = timeline.sendVideo(
 744→        fileSource,
 745→        new UploadSource.File({ filename: filePath }),
 746→        {
 747→          height: videoContent.info?.height || BigInt(0),
 748→          width: videoContent.info?.width || BigInt(0),
 749→          mimetype: videoContent.info?.mimetype || "video/mp4",
 750→          size: videoContent.info?.size || BigInt(0),
 751→          duration: videoContent.info?.duration || 0,
 752→          thumbnailInfo: videoContent.info?.thumbnailInfo,
 753→          thumbnailSource: undefined,
 754→          blurhash: videoContent.info?.blurhash || "",
 755→        },
 756→      );
 757→      await videoHandle.join();
