 15→export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
 16→  navigation,
 17→}) => {
 18→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
 19→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
 20→  const hasSeenNotificationsIntro = useAtomValue(
 21→    PushNotificationsAtoms.hasSeenNotificationsIntro,
 22→  );
 23→  const transition = useRef(
 24→    animateParallel(
 25→      { opacity: [0, 1], translateY: [40, 0] },
 26→      { duration: 200 },
 27→    ),
 28→  ).current;
 29→
 30→  useEffect(() => {
 31→    const checkAuthAndNavigate = async () => {
 32→      try {
 33→        // Check if we have stored credentials
 34→        if (MatrixService.hasStoredCredentials()) {
 35→          const sessionRestored = await MatrixService.restoreSession();
 36→          const backupState = await MatrixService.getBackupState();
 37→          const recoveryState = await MatrixService.getRecoveryState();
 38→          const backupExists = backupState === "enabled";
 39→          const recoveryDisabled =
 40→            recoveryState === RecoveryState.Disabled ||
 41→            recoveryState === RecoveryState.Incomplete;
 42→          const isVerified = MatrixService.isDeviceVerified();
 43→          /** If the session is restored and the device is not verified, there is a backup and recovery is not disabled, navigate to the confirm identity screen */
 44→          const needsConfirmIdentity =
 45→            !isVerified && backupExists && !recoveryDisabled;
 46→          await MatrixService.refreshRoomList();
 47→
 48→          if (sessionRestored && needsConfirmIdentity) {
 49→            navigation.replace("confirmIdentity");
 50→            return;
 51→          }
 52→
 53→          if (!hasSeenOnboarding) {
 54→            navigation.replace("onboarding");
 55→            return;
 56→          }
 57→
 58→          if (!hasSeenNotificationsIntro) {
 59→            navigation.replace("notificationsIntro");
 60→            return;
 61→          }
 62→
 63→          //If there is a screen lock pin, navigate to the verify pin screen
 64→          if (screenLockPin && sessionRestored) {
 65→            navigation.replace("verifyPin", { isSettingsScreen: false });
 66→            return;
 67→          }
 68→
 69→          if (sessionRestored) {
 70→            // Check if app was opened from a notification
 71→            const pendingRoomId = NotifeeService.consumePendingRoomId();
 72→            if (pendingRoomId) {
 73→              navigation.reset({
 74→                index: 1,
 75→                routes: [
 76→                  { name: "home" },
 77→                  { name: "room", params: { roomId: pendingRoomId } },
 78→                ],
 79→              });
 80→              return;
 81→            }
 82→
 83→            navigation.replace("home");
 84→            return;
 85→          }
 86→        }
 87→
 88→        await MatrixService.initialize(MatrixBaseURL);
 89→        navigation.replace("welcome");
 90→      } catch (error) {
 91→        console.warn("Error during auth check:", error);
 92→        navigation.replace("welcome");
 93→      }
 94→    };
 95→
 96→    transition.start(() => {
 97→      setTimeout(checkAuthAndNavigate, 2000);
 98→    });
 99→  }, [navigation, hasSeenOnboarding, screenLockPin, transition]);
100→
101→  return (
102→    <ScreenLayout>
103→      <Block
104→        animations={transition.animations}
105→        flex={1}
106→        align="center"
107→        justify="space-between"
108→      >
109→        <Image
110→          source={require("assets/images/logo.png")}
111→          width={88}
112→          height={66}
113→          style={styles.logo}
114→        />
115→        <Text font="Silkscreen-Regular" size={TextSize.medium}>
116→          CLOAK
117→        </Text>
118→      </Block>
119→    </ScreenLayout>
120→  );
121→};
